package com.minimalpairs.app.data.audio

import com.minimalpairs.app.core.dsp.WavCodec
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.sync.withLock
import minimalpairs.composeapp.generated.resources.Res

/**
 * Loads bundled 16kHz 16-bit mono PCM WAV files generated by ElevenLabs
 * from Compose Multiplatform resources (`composeResources/files/audio/`).
 */
object ElevenLabsAudioRepository {
    private val cacheMutex = Mutex()
    private val pcmCache = mutableMapOf<String, ShortArray>()

    suspend fun loadWordPcm(word: String): ShortArray? {
        val normalized = word.trim().lowercase()
        return loadPcmAtPath("files/audio/words/$normalized.wav")
    }

    suspend fun loadProsodyPcm(patternId: String): ShortArray? {
        return loadPcmAtPath("files/audio/prosody/${patternId.trim()}.wav")
    }

    suspend fun loadMeaningTrapPromptPcm(storyId: String): ShortArray? {
        return loadPcmAtPath("files/audio/meaning_trap/${storyId.trim()}_prompt.wav")
    }

    suspend fun loadMeaningTrapPhrasePcm(storyId: String): ShortArray? {
        return loadPcmAtPath("files/audio/meaning_trap/${storyId.trim()}_phrase.wav")
    }

    suspend fun loadMeaningTrapOutcomePcm(storyId: String, isIntendedSuccess: Boolean): ShortArray? {
        val suffix = if (isIntendedSuccess) "intended" else "trap"
        return loadPcmAtPath("files/audio/meaning_trap/${storyId.trim()}_$suffix.wav")
    }

    private suspend fun loadPcmAtPath(resourcePath: String): ShortArray? {
        cacheMutex.withLock {
            pcmCache[resourcePath]?.let { return it }
        }
        return try {
            val bytes = Res.readBytes(resourcePath)
            val pcm = WavCodec.decodeWavToPcm(bytes)
            if (pcm.isNotEmpty()) {
                cacheMutex.withLock {
                    pcmCache[resourcePath] = pcm
                }
                pcm
            } else {
                null
            }
        } catch (cancelled: CancellationException) {
            throw cancelled
        } catch (_: Exception) {
            null
        }
    }
}
